L10_1.m_SubTitle_KOREA = "<color=#ffd34c>\226\150\160\226\150\160</color> \235\176\169\235\176\169 \235\155\176\235\138\148 \234\177\176\235\180\144! \235\132\136\235\172\180 \234\183\128\236\151\189\236\158\150\236\149\132!\n<color=#ffd34c>\226\150\160\226\150\160</color> \236\151\144\235\166\172\236\150\180\236\138\164\235\143\132 \237\140\140\236\157\180\237\140\133!!\n<color=#ffd34c>\226\150\160\226\150\160\226\150\160</color> \236\161\176\235\148\148\236\149\133 \235\130\152\236\157\180\236\184\160 \236\131\157\234\176\129\235\179\180\235\139\164 \236\167\132\236\167\156 \236\158\152\237\149\156\235\139\164!\n<color=#ffd34c>\226\150\160\226\150\160\226\150\160</color> \236\185\180\235\130\152\235\166\172\236\149\132\234\176\128 \236\149\132\235\172\180\234\178\131\235\143\132 \235\170\187\237\149\152\234\179\160 \236\158\136\236\150\180!\n<color=#ffd34c>\226\150\160 \226\150\160</color> \237\149\168\236\132\160\236\157\132 \236\149\132\236\152\136 \235\170\187 \236\147\176\235\138\148 \234\177\176 \235\179\180\235\169\180, \236\160\132 \234\178\189\234\184\176\236\151\144 \236\151\172\237\140\140\234\176\128 \236\158\136\235\130\152\235\180\144."
