L10_1.m_SubTitle_JPN = "<color=#ffd34c>\226\150\160\226\150\160</color> \227\131\148\227\131\167\227\131\179\227\131\148\227\131\167\227\131\179\232\183\179\227\129\173\227\129\166\227\130\139\239\188\129\227\128\128\229\143\175\230\132\155\227\129\153\227\129\142\239\188\129\n<color=#ffd34c>\226\150\160\226\150\160</color> \227\130\162\227\131\170\227\130\166\227\130\185\227\130\130\227\131\149\227\130\161\227\130\164\227\131\136\239\188\129\239\188\129\n<color=#ffd34c>\226\150\160\226\150\160\226\150\160</color> \227\130\190\227\131\135\227\130\163\227\130\162\227\131\131\227\130\175\227\131\138\227\130\164\227\131\132\227\128\129\230\128\157\227\129\163\227\129\159\227\130\136\227\130\138\228\184\138\230\137\139\227\129\152\227\130\131\227\130\147\239\188\129\n<color=#ffd34c>\226\150\160\226\150\160\226\150\160</color> \227\130\171\227\131\138\227\131\170\227\130\162\227\129\175\228\189\149\227\130\130\227\129\167\227\129\141\227\129\166\227\129\170\227\129\132\227\130\136\239\188\129\n<color=#ffd34c>\226\150\160 \226\150\160</color> \232\137\166\232\136\185\227\130\146\229\133\168\231\132\182\228\189\191\227\129\136\227\129\166\227\129\170\227\129\132\227\129\174\227\130\146\232\166\139\227\130\139\227\129\168\227\128\129\227\129\147\227\129\174\229\137\141\227\129\174\232\169\166\229\144\136\227\129\140\233\159\191\227\129\132\227\129\166\227\130\139\227\130\136\227\129\134\227\129\160\227\129\170\227\128\130"
L10_1.m_SubTitle_ENG = "<color=#ffd34c>\226\150\160\226\150\160</color> She's so cute jumping up and down like that!\n<color=#ffd34c>\226\150\160\226\150\160</color> I'm rooting for you, Arius!!\n<color=#ffd34c>\226\150\160\226\150\160\226\150\160</color> The Zodiac Knights are doing better than I thought!\n<color=#ffd34c>\226\150\160\226\150\160\226\150\160</color> The Canary is unable to do anything!\n<color=#ffd34c>\226\150\160 \226\150\160</color> Seeing how they're not using their ship, the aftermath of their last match seems to be affecting them more than they thought."
