L10_1.m_SubTitle_VTN = "<color=#ffd34c>\226\150\160\226\150\160</color> C\195\180 b\195\169 nh\225\186\163y l\195\170n nh\225\186\163y xu\225\187\145ng d\225\187\133 th\198\176\198\161ng qu\195\161!\n<color=#ffd34c>\226\150\160\226\150\160</color> T\195\180i \225\187\167ng h\225\187\153 c\195\180 b\195\169, Arius!!\n<color=#ffd34c>\226\150\160\226\150\160</color> C\195\161c Hi\225\187\135p S\196\169 Ho\195\160ng \196\144\225\186\161o \196\145ang l\195\160m t\225\187\145t h\198\161n t\195\180i ngh\196\169!\n<color=#ffd34c>\226\150\160\226\150\160</color> Chim ho\195\160ng y\225\186\191n kh\195\180ng th\225\187\131 l\195\160m g\195\172 \196\145\198\176\225\187\163c!\n<color=#ffd34c>\226\150\160\226\150\160</color> Nh\195\172n h\225\187\141 kh\195\180ng s\225\187\173 d\225\187\165ng t\195\160u c\225\187\167a m\195\172nh k\195\172a, h\225\186\173u qu\225\186\163 c\225\187\167a tr\225\186\173n \196\145\225\186\165u tr\198\176\225\187\155c c\195\179 v\225\186\187 \196\145ang \225\186\163nh h\198\176\225\187\159ng nhi\225\187\129u h\198\161n h\225\187\141 t\198\176\225\187\159ng."
L10_1.m_SubTitle_SCN = "<color=#ffd34c>\226\150\160\226\150\160</color>\231\156\139\229\165\185\232\185\166\232\185\166\232\183\179\232\183\179\231\154\132\230\160\183\229\173\144\239\188\129\231\156\159\231\154\132\229\165\189\229\143\175\231\136\177\239\188\129\n<color=#ffd34c>\226\150\160\226\150\160</color>\229\159\131\233\135\140\229\165\165\230\150\175\228\185\159\232\166\129\229\138\160\230\178\185\229\149\138\239\188\129\239\188\129\n<color=#ffd34c>\226\150\160\226\150\160\226\150\160</color>\229\141\129\228\186\140\229\174\171\233\170\145\229\163\171\231\154\132\229\174\158\229\138\155\230\175\148\230\136\145\230\131\179\229\190\151\232\191\152\232\166\129\229\142\137\229\174\179\229\149\138\239\188\129\n<color=#ffd34c>\226\150\160\226\150\160\226\150\160</color>\233\135\145\228\184\157\233\155\128\229\176\143\233\152\159\231\142\176\229\156\168\228\187\128\228\185\136\233\131\189\229\129\154\228\184\141\228\186\134\239\188\129\n<color=#ffd34c>\226\150\160 \226\150\160</color>\230\160\185\230\156\172\228\184\141\232\131\189\231\148\168\232\136\176\232\136\185\239\188\140\231\156\139\230\160\183\229\173\144\230\152\175\229\143\151\229\136\176\228\186\134\228\184\138\228\184\128\228\184\170\230\175\148\232\181\155\231\154\132\229\189\177\229\147\141\227\128\130"
L10_1.m_SubTitle_DEU = "<color=#ffd34c>\226\150\160\226\150\160</color> Schaut mal, wie sie auf- und abh\195\188pft! Sie ist so knuffig!\n<color=#ffd34c>\226\150\160\226\150\160</color> Ich bin auf deiner Seite, Arius!!\n<color=#ffd34c>\226\150\160\226\150\160\226\150\160</color> Die Sternenritter sind viel besser als erwartet!\n<color=#ffd34c>\226\150\160\226\150\160\226\150\160</color> Der Canary Trupp kann nichts gegen sie ausrichten!\n<color=#ffd34c>\226\150\160 \226\150\160</color> Die Tatsache, dass sie ihr Schiff beim letzten Spiel geschrottet haben, wird ihnen jetzt zum Verh\195\164ngnis."
L10_1.m_SubTitle_FRA = "<color=#ffd34c>\226\150\160\226\150\160</color> Regardez-les courir partout ! C'est trop mignon !\n<color=#ffd34c>\226\150\160\226\150\160</color> Courage \195\160 toi, Arius !\n<color=#ffd34c>\226\150\160\226\150\160\226\150\160</color> Les Chevaliers du Zodiaque sont bien meilleurs que je pensais !\n<color=#ffd34c>\226\150\160\226\150\160\226\150\160</color> Les canaris sont compl\195\168tement \195\160 la ramasse !\n<color=#ffd34c>\226\150\160 \226\150\160</color> \195\137tant donn\195\169 qu'elles ne peuvent pas utiliser leur vaisseau, \195\167a impacte tout le match."
